-- 페이징도 손으로

public List<Member> findByPage(int age, int offset, int limit) {
    return em.createQuery(
            "select m from Member m where m.age = :age" +
            " order by m.username desc", Member.class)
        .setParameter("age", age)
        .setFirstResult(offset)
        .setMaxResults(limit)
        .getResultList();
}

public long totalCount(int age) {
    return em.createQuery(
            "select count(m) from Member m where m.age = :age", Long.class)
        .setParameter("age", age)
        .getSingleResult();
}

@Test
@Transactional
void 페이징() {
    for (int i = 0; i < 5; i++) em.persist(new Member("p" + i, 10));
    em.flush(); em.clear();

    List<Member> page = memberJpaRepository.findByPage(10, 0, 3);
    long total = memberJpaRepository.totalCount(10);
    System.out.println("이 페이지 " + page.size() + "건, 전체 " + total + "건");
}

